630	func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, w, errW io.Writer, point RewindPoint, force bool) ([]RestoredSession, error) {
631		if !point.IsLogsOnly {
632			return nil, errors.New("not a logs-only rewind point")
633		}
634	
635		if point.CheckpointID.IsEmpty() {
636			return nil, errors.New("missing checkpoint ID")
637		}
638	
639		repo, err := OpenRepository(ctx)
640		if err != nil {
641			return nil, fmt.Errorf("failed to open git repository: %w", err)
642		}
643		defer repo.Close()
644	
645		WarnIfMetadataDisconnected()
646		stores, err := cpkg.Open(ctx, repo, cpkg.OpenOptions{BlobFetcher: s.blobFetcher})
647		if err != nil {
648			return nil, fmt.Errorf("open checkpoint store: %w", err)
649		}
650		store := stores.Persistent
651		summary, err := cpkg.ReadCheckpoint(ctx, store, point.CheckpointID)
652		if err != nil {
653			return nil, fmt.Errorf("failed to read checkpoint: %w", err)
654		}
655		if err := checkpointpolicy.EnsureCanReadVersion(point.CheckpointID.String(), summary.CheckpointVersion); err != nil {
656			return nil, err
657		}
658	
659		// Get worktree root for agent session directory lookup
660		repoRoot, err := paths.WorktreeRoot(ctx)
661		if err != nil {
662			return nil, fmt.Errorf("failed to get worktree root: %w", err)
663		}
664	
665		// By default (no --force), never overwrite a session log that already exists
666		// locally: the on-disk transcript is the live session being resumed, so we
667		// keep it and only restore logs that are missing. The write loop below skips
668		// any session whose ID is in skipExisting but still reports it so the caller
669		// prints its resume command. --force overwrites everything from the checkpoint.
670		skipExisting := map[string]bool{}
671		if !force {
672			for _, sess := range s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary) {
673				if sess.Status != StatusNew {
674					skipExisting[sess.SessionID] = true
675				}
676			}
677		}
678	
679		// Count sessions to restore
680		totalSessions := len(summary.Sessions)
681		if totalSessions > 1 {
682			fmt.Fprintf(w, "Restoring %d sessions from checkpoint:\n", totalSessions)
683		}
684	
685		// Restore all sessions (oldest to newest, using 0-based indexing)
686		var restored []RestoredSession
687		for i := range totalSessions {
688			content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
689			if readErr != nil {
690				if !errors.Is(readErr, cpkg.ErrNoTranscript) {
691					fmt.Fprintf(errW, "  Warning: failed to read session %d: %v\n", i, readErr)
692				}
693				continue
694			}
695			if content == nil || len(content.Transcript) == 0 {
696				continue
697			}
698	
699			sessionID := content.Metadata.SessionID
700			if sessionID == "" {
701				fmt.Fprintf(errW, "  Warning: session %d has no session ID, skipping\n", i)
702				continue
703			}
704			// Checkpoint metadata comes from the shared entire/checkpoints/v1 branch
705			// and is attacker-influenceable. Reject path separators/absolute IDs before
706			// they reach ResolveSessionFile + Session, which would otherwise let a
707			// crafted session ID overwrite files outside the agent session directory.
708			if err := validation.ValidateSessionID(sessionID); err != nil {
709				fmt.Fprintf(errW, "  Warning: session %d has unsafe session ID %q, skipping: %v\n", i, sessionID, err)
710				continue
711			}
712	
713			// Resolve per-session agent from metadata — skip if agent is unknown
714			if content.Metadata.Agent == "" {
715				fmt.Fprintf(errW, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
716				continue
717			}
718			sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
719			if agErr != nil {
720				fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
721				continue
722			}
723	
724			// Compute transcript path from current repo location for cross-machine portability.
725			sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
726			if dirErr != nil {
727				fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
728				continue
729			}
730			sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
731			if resolver, ok := sessionAgent.(agent.RestoredSessionPathResolver); ok {
732				resolvedFile, resolveErr := resolver.ResolveRestoredSessionFile(sessionAgentDir, sessionID, content.Transcript)
733				if resolveErr != nil {
734					fmt.Fprintf(errW, "  Warning: failed to resolve restored session path for session %d (%s): %v (using fallback path)\n", i, sessionID, resolveErr)
735				} else {
736					sessionFile = resolvedFile
737				}
738			}
739	
740			// Get first prompt for display
741			promptPreview := ExtractFirstPrompt(content.Prompts)
742	
743			// Local log already present and not forcing: keep it untouched, but still
744			// report the session so the caller can print its resume command.
745			if skipExisting[sessionID] {
746				if totalSessions > 1 {
747					fmt.Fprintf(w, "  Session %d: keeping existing local log\n", i+1)
748				} else {
749					fmt.Fprintf(w, "Keeping existing local session log\n")
750				}
751				restored = append(restored, RestoredSession{
752					SessionID: sessionID,
753					Agent:     sessionAgent.Type(),
754					Prompt:    promptPreview,
755					CreatedAt: content.Metadata.CreatedAt,
756				})
757				continue
758			}
759	
760			if totalSessions > 1 {
761				isLatest := i == totalSessions-1
762				if promptPreview != "" {
763					if isLatest {
764						fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
765					} else {
766						fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
767					}
768				}
769				fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
770			} else {
771				fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
772			}
773	
774			// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
775			if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
776				fmt.Fprintf(errW, "    Warning: failed to create directory: %v\n", mkdirErr)
777				continue
778			}
779	
780			agentSession := &agent.AgentSession{
781				SessionID:  sessionID,
782				AgentName:  sessionAgent.Name(),
783				RepoPath:   repoRoot,
784				SessionRef: sessionFile,
785				NativeData: content.Transcript,
786			}
787			if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
788				if totalSessions > 1 {
789					fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
790					continue
791				}
792				return nil, fmt.Errorf("failed to write session: %w", writeErr)
793			}
794	
795			restored = append(restored, RestoredSession{
796				SessionID: sessionID,
797				Agent:     sessionAgent.Type(),
798				Prompt:    promptPreview,
799				CreatedAt: content.Metadata.CreatedAt,
800			})
801		}
802	
803		return restored, nil
804	}
