815	// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
816	// Returns an empty string if the prompt cannot be read.
817	func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
818		// Get the commit and its tree
819		commit, err := repo.CommitObject(commitHash)
820		if err != nil {
821			return ""
822		}
823	
824		tree, err := commit.Tree()
825		if err != nil {
826			return ""
827		}
828	
829		// Look for prompt.txt in the metadata directory
830		promptPath := metadataDir + "/" + paths.PromptFileName
831		promptEntry, err := tree.File(promptPath)
832		if err != nil {
833			return ""
834		}
835	
836		content, err := promptEntry.Contents()
837		if err != nil {
838			return ""
839		}
840	
841		return ExtractFirstPrompt(content)
842	}
