854	// SessionRestoreInfo contains information about a session being restored.
855	type SessionRestoreInfo struct {
856		SessionID      string
857		Prompt         string               // First prompt preview for display
858		Status         SessionRestoreStatus // Status of this session
859		LocalTime      time.Time
860		CheckpointTime time.Time
