863	// classifySessionsForRestore checks all sessions in a checkpoint and returns info
864	// about each session, including whether local logs have newer timestamps.
865	// repoRoot is used to compute per-session agent directories.
866	// Sessions without agent metadata are skipped (cannot determine target directory).
867	func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.SessionReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
868		var sessions []SessionRestoreInfo
869	
870		totalSessions := len(summary.Sessions)
871		// Check all sessions (0-based indexing)
872		for i := range totalSessions {
873			content, err := store.ReadSessionContent(ctx, checkpointID, i)
874			if err != nil || content == nil || len(content.Transcript) == 0 {
875				continue
876			}
877	
878			sessionID := content.Metadata.SessionID
879			if sessionID == "" || content.Metadata.Agent == "" {
880				continue
881			}
882			// Skip unsafe session IDs (see RestoreLogsOnly): this path stats the resolved
883			// transcript file, so a crafted ID could otherwise probe arbitrary locations.
884			if validation.ValidateSessionID(sessionID) != nil {
885				continue
886			}
887	
888			sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
889			if agErr != nil {
890				continue
891			}
892	
893			// Compute transcript path from current repo location for cross-machine portability.
894			sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
895			if dirErr != nil {
896				continue
897			}
898			localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
899	
900			localTime := paths.GetLastTimestampFromFile(localPath)
901			checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
902			status := ClassifyTimestamps(localTime, checkpointTime)
903			// ClassifyTimestamps reports StatusNew when the local file has no parseable
904			// timestamp — but a present-but-untimestamped log still exists and must not
905			// be silently overwritten. Only a truly-absent file counts as new.
906			if status == StatusNew {
907				if _, statErr := os.Stat(localPath); statErr == nil {
908					status = StatusUnchanged
909				}
910			}
911	
912			sessions = append(sessions, SessionRestoreInfo{
913				SessionID:      sessionID,
914				Prompt:         ExtractFirstPrompt(content.Prompts),
915				Status:         status,
916				LocalTime:      localTime,
917				CheckpointTime: checkpointTime,
918			})
919		}
920	
921		return sessions
922	}
923	
924	// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
925	func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
926		// Local file doesn't exist (no timestamp found)
927		if localTime.IsZero() {
928			return StatusNew
929		}
930	
931		// Can't determine checkpoint time - treat as new/safe
932		if checkpointTime.IsZero() {
933			return StatusNew
934		}
935	
936		// Compare timestamps
937		if localTime.After(checkpointTime) {
938			return StatusLocalNewer
939		}
940		if checkpointTime.After(localTime) {
941			return StatusCheckpointNewer
942		}
943		return StatusUnchanged
944	}
