946	// StatusToText returns a human-readable status string.
947	func StatusToText(status SessionRestoreStatus) string {
948		switch status {
949		case StatusNew:
950			return "(new)"
951		case StatusUnchanged:
952			return "(unchanged)"
953		case StatusCheckpointNewer:
954			return "(checkpoint is newer)"
955		case StatusLocalNewer:
956			return "(local is newer)" // shouldn't appear in non-conflict list
957		default:
958			return ""
959		}
960	}
