962	// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
963	// session logs that have newer timestamps than the checkpoint versions.
964	func PromptOverwriteNewerLogs(errW io.Writer, sessions []SessionRestoreInfo) (bool, error) {
965		if !interactive.CanPromptInteractively() {
966			return false, errors.New("cannot prompt to overwrite local session logs in non-interactive mode; rerun with --force to overwrite or use a TTY to confirm")
967		}
968	
969		// Separate conflicting and non-conflicting sessions
970		var conflicting, nonConflicting []SessionRestoreInfo
971		for _, s := range sessions {
972			if s.Status == StatusLocalNewer {
973				conflicting = append(conflicting, s)
974			} else {
975				nonConflicting = append(nonConflicting, s)
976			}
977		}
978	
979		fmt.Fprintf(errW, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
980		for _, info := range conflicting {
981			// Show prompt if available, otherwise fall back to session ID
982			if info.Prompt != "" {
983				fmt.Fprintf(errW, "  \"%s\"\n", info.Prompt)
984			} else {
985				fmt.Fprintf(errW, "  Session: %s\n", info.SessionID)
986			}
987			fmt.Fprintf(errW, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
988			fmt.Fprintf(errW, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
989		}
990	
991		// Show non-conflicting sessions with their status
992		if len(nonConflicting) > 0 {
993			fmt.Fprintf(errW, "\nThese other session(s) will also be restored:\n")
994			for _, info := range nonConflicting {
995				statusText := StatusToText(info.Status)
996				if info.Prompt != "" {
997					fmt.Fprintf(errW, "  \"%s\" %s\n", info.Prompt, statusText)
998				} else {
999					fmt.Fprintf(errW, "  Session: %s %s\n", info.SessionID, statusText)
1000				}
1001			}
1002		}
