1201	func runTrailCheckout(ctx context.Context, w, errW io.Writer, insecureHTTP bool, selector string, force bool) error {
1202		return runAuthenticatedTrailAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
1203			forge, owner, repo, err := resolveTrailRemote(ctx)
1204			if err != nil {
1205				return err
1206			}
1207	
1208			found, err := resolveTrailBySelector(ctx, client, forge, owner, repo, selector)
1209			if err != nil {
1210				return err
1211			}
1212	
1213			branch := strings.TrimSpace(found.Branch)
1214			if branch == "" {
1215				return fmt.Errorf("%s has no branch to check out", describeTrailRef(found))
1216			}
1217	
1218			currentBranch, _ := GetCurrentBranch(ctx) //nolint:errcheck // best-effort; a detached HEAD just means "not already on the branch"
1219			if currentBranch == branch {
1220				fmt.Fprintf(w, "Already on branch %s for %s.\n", branch, describeTrailRef(found))
1221				return nil
1222			}
1223	
1224			fmt.Fprintf(w, "Checking out %s\n", describeTrailRef(found))
1225			// switchToBranchForResume handles local vs. remote-only branches, the
1226			// uncommitted-changes guard, and the fetch prompt; reuse it rather than
1227			// re-deriving that logic here.
1228			proceed, err := switchToBranchForResume(ctx, w, errW, branch, force)
1229			if err != nil {
1230				return err
1231			}
1232			if !proceed {
1233				// The user declined to fetch a remote-only branch — a clean stop, not
1234				// an error. Say so explicitly so the preceding "Checking out …" line
1235				// doesn't read as a successful switch.
1236				fmt.Fprintf(w, "Checkout of branch %s cancelled.\n", branch)
1237			}
1238			return nil
1239		})
1240	}
