1242	// describeTrailRef renders a short human reference to a trail for status
1243	// messages, e.g. "trail #575 (Add foo)" or, when the trail has no number yet,
1244	// "trail \"Add foo\"".
1245	func describeTrailRef(t *api.TrailResource) string {
1246		title := strings.TrimSpace(t.Title)
1247		if t.Number > 0 {
1248			if title == "" {
1249				return fmt.Sprintf("trail #%d", t.Number)
1250			}
1251			return fmt.Sprintf("trail #%d (%s)", t.Number, title)
1252		}
1253		if title == "" {
1254			return "trail"
1255		}
1256		return fmt.Sprintf("trail %q", title)
1257	}
