// By default (no --force), decide per session whether to keep the existing
// local log or refresh it from the checkpoint, based on which side has the
// newer last entry:
//   - StatusNew             → restore (no local file yet).
//   - StatusUnchanged       → keep local (identical; restoring is a no-op).
//   - StatusCheckpointNewer → restore: the checkpoint has progressed beyond
//     the local log (e.g. another machine continued the session and pushed a
//     newer checkpoint). It is a strict superset, so nothing local is lost.
//   - StatusLocalNewer      → conflict: the local log has entries the
//     checkpoint doesn't. Prompt before overwriting (keep on decline / when
//     we can't prompt) so live local work is never silently clobbered.
// The write loop below skips any session whose ID is in skipExisting but
// still reports it so the caller prints its resume command. --force overwrites
// everything from the checkpoint unconditionally.
skipExisting := map[string]bool{}
statusByID := map[string]SessionRestoreStatus{}
if !force {
	var conflicts []SessionRestoreInfo
	for _, sess := range s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary) {
		statusByID[sess.SessionID] = sess.Status
		switch sess.Status {
