10	
11	// GetLastTimestampFromFile reads the last non-empty line from a JSONL file
12	// and extracts the timestamp field. Returns zero time if file doesn't exist
13	// or no valid timestamp is found.
14	func GetLastTimestampFromFile(path string) time.Time {
15		file, err := os.Open(path) //nolint:gosec // path is from controlled session directory
16		if err != nil {
17			return time.Time{}
18		}
19		defer file.Close()
20	
21		var lastLine string
22		scanner := bufio.NewScanner(file)
23		for scanner.Scan() {
24			line := scanner.Text()
25			if line != "" {
26				lastLine = line
27			}
28		}
29	
30		return ParseTimestampFromJSONL(lastLine)
31	}
32	
33	// GetLastTimestampFromBytes extracts the timestamp from the last non-empty line
34	// of JSONL content. Returns zero time if not found.
35	func GetLastTimestampFromBytes(data []byte) time.Time {
36		var lastLine string
37		scanner := bufio.NewScanner(bytes.NewReader(data))
38		for scanner.Scan() {
39			line := scanner.Text()
40			if line != "" {
41				lastLine = line
42			}
43		}
44	
45		return ParseTimestampFromJSONL(lastLine)
46	}
47	
48	// ParseTimestampFromJSONL extracts the timestamp from a JSONL line.
49	// Returns zero time if the line is empty or doesn't contain a valid timestamp.
50	func ParseTimestampFromJSONL(line string) time.Time {
51		if line == "" {
52			return time.Time{}
53		}
54	
55		var entry struct {
56			Timestamp string `json:"timestamp"`
57		}
58		if err := json.Unmarshal([]byte(line), &entry); err != nil {
59			return time.Time{}
60		}
61	
62		t, err := time.Parse(time.RFC3339, entry.Timestamp)
63		if err != nil {
64			return time.Time{}
65		}
66		return t
67	}
