// Decide per session whether to keep the existing local log or refresh it
// from the checkpoint. The write loop below skips any session whose ID is in
// skipExisting but still reports it so the caller prints its resume command;
// statusByID lets it explain why an existing log is being overwritten.
skipExisting, statusByID := s.decideRestoreActions(ctx, repoRoot, store, point.CheckpointID, summary, errW, force)

// decideRestoreActions classifies every session in the checkpoint and returns
// the per-session restore decision under the default (non-force) resume policy,
// based on which side has the newer last entry:
//   - StatusNew             → restore (no local file yet).
//   - StatusUnchanged       → keep local (identical; restoring is a no-op).
//   - StatusCheckpointNewer → restore: the checkpoint has progressed beyond the
//     local log (e.g. another machine continued the session and pushed a newer
//     checkpoint). It is a strict superset, so nothing local is lost.
//   - StatusLocalNewer      → conflict: the local log has entries the checkpoint
//     doesn't. Prompt before overwriting (keep on decline / when we can't prompt)
//     so live local work is never silently clobbered.
//
// With force, everything is restored unconditionally (both maps are empty).
// skipExisting holds the IDs to keep untouched; statusByID maps every classified
// session to its status so callers can explain an overwrite.
func (s *ManualCommitStrategy) decideRestoreActions(ctx context.Context, repoRoot string, store cpkg.SessionReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary, errW io.Writer, force bool) (skipExisting map[string]bool, statusByID map[string]SessionRestoreStatus) {
	skipExisting = map[string]bool{}
	statusByID = map[string]SessionRestoreStatus{}
	if force {
		return skipExisting, statusByID
	}

	var conflicts []SessionRestoreInfo
	for _, sess := range s.classifySessionsForRestore(ctx, repoRoot, store, checkpointID, summary) {
		statusByID[sess.SessionID] = sess.Status
		switch sess.Status {
		case StatusUnchanged:
			skipExisting[sess.SessionID] = true
		case StatusLocalNewer:
			conflicts = append(conflicts, sess)
		case StatusNew, StatusCheckpointNewer:
			// Restore: nothing local would be lost.
		}
	}
	if len(conflicts) > 0 && !ConfirmOverwriteNewerLocalLogs(errW, conflicts) {
		for _, sess := range conflicts {
			skipExisting[sess.SessionID] = true
		}
	}
	return skipExisting, statusByID
}

