// TestResume_ExistingLocalLog_RefreshedWhenCheckpointNewer verifies that an
// existing local log is refreshed from the checkpoint without --force when the
// checkpoint transcript is newer than the local copy. This is the cross-machine
// case: the session was continued and a newer checkpoint pushed from another
// machine, so the stale local log must be brought up to date (the checkpoint is
// a strict superset; nothing local is lost).
func TestResume_ExistingLocalLog_RefreshedWhenCheckpointNewer(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	// Create a session
	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	content := "def hello; end"
	env.WriteFile("hello.rb", content)

	session.CreateTranscript(
		"Create hello method",
		[]FileChange{{Path: "hello.rb", Content: content}},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Commit the session's changes (manual-commit requires user to commit)
	env.GitCommitWithShadowHooks("Create hello method", "hello.rb")

	featureBranch := env.GetCurrentBranch()

	// Create a local log with an OLDER timestamp than the checkpoint
	if err := os.MkdirAll(env.ClaudeProjectDir, 0o755); err != nil {
		t.Fatalf("failed to create Claude project dir: %v", err)
	}
	existingLog := filepath.Join(env.ClaudeProjectDir, session.ID+".jsonl")
	// Use a timestamp far in the past
	pastTimestamp := time.Now().Add(-7 * 24 * time.Hour).UTC().Format(time.RFC3339)
	olderContent := fmt.Sprintf(`{"type":"human","timestamp":"%s","message":{"content":"older local work"}}`, pastTimestamp)
	if err := os.WriteFile(existingLog, []byte(olderContent), 0o644); err != nil {
		t.Fatalf("failed to write existing log: %v", err)
	}

	// Switch to main
	env.GitCheckoutBranch(masterBranch)

	// Resume WITHOUT --force should succeed and refresh the stale local log.
	output, err := env.RunResume(featureBranch)
	if err != nil {
		t.Fatalf("resume failed (should succeed and refresh the stale log): %v\nOutput: %s", err, output)
	}
	if !strings.Contains(output, "Checkpoint has newer entries") {
		t.Errorf("output should indicate the local log was refreshed from the checkpoint, got: %s", output)
	}

	// Verify local log WAS overwritten with the checkpoint transcript.
	data, err := os.ReadFile(existingLog)
	if err != nil {
		t.Fatalf("failed to read log: %v", err)
	}
	if strings.Contains(string(data), "older local work") {
		t.Errorf("stale local log should have been refreshed from the checkpoint, but still has old content: %s", string(data))
	}
	if !strings.Contains(string(data), "Create hello method") {
		t.Errorf("refreshed log should contain the checkpoint transcript, got: %s", string(data))
	}
}

