130	// flattenCheckpointEntries reads only the entries under a specific checkpoint path
131	// from the sessions branch tree. This is O(files in checkpoint) instead of O(all checkpoints).
132	// Returns an empty map if the checkpoint doesn't exist yet.
133	func (s *GitStore) flattenCheckpointEntries(rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
134		entries := make(map[string]object.TreeEntry)
135		if rootTreeHash == plumbing.ZeroHash {
136			return entries, nil
137		}
138	
139		rootTree, err := s.repo.TreeObject(rootTreeHash)
140		if err != nil {
141			if errors.Is(err, plumbing.ErrObjectNotFound) {
142				return entries, nil // Tree doesn't exist yet
143			}
144			return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
145		}
146	
147		subtree, err := rootTree.Tree(checkpointPath)
148		if err != nil {
149			return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
150		}
151	
152		// Flatten just this subtree with the full path prefix
153		if err := FlattenTree(s.repo, subtree, checkpointPath, entries); err != nil {
154			return nil, err
155		}
156		return entries, nil
157	}
