159	// spliceCheckpointSubtree builds a tree from checkpoint-local entries and installs it
160	// at the correct shard location in the root tree using O(depth) tree surgery.
161	// basePath is like "a3/b2c4d5e6f7/" (with trailing slash).
162	// Returns the new root tree hash.
163	func (s *GitStore) spliceCheckpointSubtree(ctx context.Context, rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
164		// Convert entries to relative paths (strip basePath prefix)
165		relEntries := make(map[string]object.TreeEntry, len(entries))
166		for path, entry := range entries {
167			relPath := strings.TrimPrefix(path, basePath)
168			if relPath == path {
169				continue // Entry doesn't have the expected prefix
170			}
171			relEntries[relPath] = entry
172		}
173	
174		// Build the checkpoint subtree from relative entries
175		checkpointTreeHash, err := BuildTreeFromEntries(ctx, s.repo, relEntries)
176		if err != nil {
177			return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
178		}
179	
180		// Splice into root tree at the shard path using tree surgery
181		// Path: ["a3"] with entry "b2c4d5e6f7" pointing to the checkpoint tree
182		shardPrefix := string(checkpointID[:2])
183		shardSuffix := string(checkpointID[2:])
184		return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
185			{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
186		}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
187	}
