302	func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteOptions, basePath string, entries map[string]object.TreeEntry) error {
303		// Read existing summary to get current session count
304		var existingSummary *CheckpointSummary
305		metadataPath := basePath + paths.MetadataFileName
306		if entry, exists := entries[metadataPath]; exists {
307			existing, err := s.readSummaryFromBlob(entry.Hash)
308			if err == nil {
309				existingSummary = existing
310			} else {
311				logging.Debug(ctx, "writeStandardCheckpointEntries: readSummaryFromBlob failed",
312					slog.String("metadata_path", metadataPath),
313					slog.String("error", err.Error()))
314			}
315		}
316	
317		// Determine session index: reuse existing slot if session ID matches, otherwise append
318		sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
319	
320		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
321		// findSessionIndex only returns 0 when existingSummary is nil (fresh write)
322		// or when the summary claims slot 0 belongs to us — either way, the tree
323		// actually holding session-0 metadata for someone else is a corruption /
324		// stale-summary shape. Writing through it would overwrite data we don't
325		// know about. Bail instead of silently clobbering.
326		//
327		// We read and capture BEFORE writeSessionToSubdirectory clears the subtree,
328		// otherwise we'd only ever see our own write.
329		if sessionIndex == 0 {
330			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
331				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
332					logging.Error(ctx, "refusing checkpoint write: session 0 holds a different sessionID",
333						slog.String("checkpoint_id", opts.CheckpointID.String()),
334						slog.String("existing_session_id", existingMeta.SessionID),
335						slog.String("write_session_id", opts.SessionID),
336						slog.Bool("existing_summary_nil", existingSummary == nil))
337					return fmt.Errorf(
338						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree entire/checkpoints/v1 %s/`",
339						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, opts.CheckpointID.Path(),
340					)
341				}
342			}
343		}
344	
345		// Write session files to numbered subdirectory
346		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
347		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
348		if err != nil {
349			return err
350		}
351	
352		// Copy additional metadata files from directory if specified (to session subdirectory)
353		if opts.MetadataDir != "" {
354			if err := s.copyMetadataDir(ctx, opts.MetadataDir, sessionPath, entries); err != nil {
355				return fmt.Errorf("failed to copy metadata directory: %w", err)
356			}
357		}
358	
359		// Build the sessions array
360		var sessions []SessionFilePaths
361		if existingSummary != nil {
362			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
363			copy(sessions, existingSummary.Sessions)
364		} else {
365			sessions = make([]SessionFilePaths, 1)
366		}
367		sessions[sessionIndex] = sessionFilePaths
368	
369		// Tripwire: an unreproduced production report had session 0 silently
370		// replaced with a different sessionID's data. The symptom was
371		// findSessionIndex returning 0 when it should have returned N
372		// (append). That happens if existingSummary is nil — yet the
373		// on-disk tree clearly had session 0's metadata. If we're writing
374		// at sessionIndex=0 while entries has pre-existing session-0
375		// metadata with a DIFFERENT sessionID, that's the exact bug shape.
376		// Loud WARN so we get a log trace instead of only the symptom.
377		if sessionIndex == 0 {
378			path := fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)
379			if entry, exists := entries[path]; exists {
380				if existingMeta, readErr := s.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
381					logging.Warn(ctx, "checkpoint write overwrites session 0 with a different sessionID — potential overwrite regression",
382						slog.String("checkpoint_id", opts.CheckpointID.String()),
383						slog.String("existing_session_id", existingMeta.SessionID),
384						slog.String("write_session_id", opts.SessionID),
385						slog.Bool("existing_summary_nil", existingSummary == nil))
386				}
387			}
388		}
389	
390		// Update root metadata.json with CheckpointSummary
391		return s.writeCheckpointSummary(opts, basePath, entries, sessions)
392	}
